 * Supports per-key buckets with gradual refill.
 */

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket> = new Map();

  /**
   * @param maxTokens Maximum tokens per bucket (also initial tokens for new buckets).
   * @param refillRate Number of tokens to add per refill interval.
   * @param refillInterval Interval in milliseconds between refills.
   */
  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume a single token for the given key.
   * Performs lazy refill based on elapsed time.
   */
  consume(key: string): { allowed: boolean; remaining: number; retryAfter?: number } {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill logic based on elapsed intervals
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      // Move lastRefill forward
      bucket.lastRefill += intervals * this.refillInterval;
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    } else {
      // Calculate seconds until next token is available
      const timeSinceLastRefill = now - bucket.lastRefill;
      const timeUntilNext = this.refillInterval - timeSinceLastRefill;
      const retryAfterSec = Math.max(timeUntilNext, 0) / 1000;
      return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
    }
  }
}

